<script lang="ts">
 import{prepareNotifications}from'./lib/desktop-notifications';import{onDestroy}from'svelte';import{Api}from'./lib/api';import type{Channel,NotificationPreferences,NotifyMode}from'./lib/api';import type{DeviceNotifications}from'./lib/social';
 export let api:Api;export let preferences:NotificationPreferences;export let device:DeviceNotifications;export let channel:Channel|undefined;export let onSaved:(p:NotificationPreferences)=>void;export let onDevice:(p:DeviceNotifications)=>void;
 const abort=new AbortController();let alive=true,previewAudio:HTMLAudioElement|undefined;onDestroy(()=>{alive=false;abort.abort();previewAudio?.pause();});
 let serverMode=preferences.notify,channelMode=channel?preferences.channels[channel.id]??'default':'default',allowDms=preferences.allow_dms,busy=false,error='',status='';
 let permission:NotificationPermission|'unsupported'=typeof Notification==='undefined'?'unsupported':Notification.permission;
 async function save(event:SubmitEvent){event.preventDefault();busy=true;error='';status='';try{const saved=await api.request<NotificationPreferences>('/me/preferences','PATCH',{notify:serverMode,allow_dms:allowDms,...(channel?{channels:{[channel.id]:channelMode==='default'?null:channelMode}}:{})},abort.signal);if(!alive)return;onSaved(saved);status='Preferences saved.';}catch(cause){if(alive)error=cause instanceof Error?cause.message:'Preferences could not be saved.';}finally{if(alive)busy=false;}}
 async function desktop(){if(typeof Notification==='undefined')return;try{permission=await Notification.requestPermission();if(permission==='granted')await prepareNotifications();onDevice({...device,desktop:permission==='granted'});status=permission==='granted'?'Browser notifications enabled on this device.':'Notifications were not enabled. You can change permission in your browser settings.';}catch{error='This browser could not enable notifications.';}}
 async function testSound(){previewAudio?.pause();const audio=new Audio('/sounds/notification.mp3');previewAudio=audio;audio.volume=device.volume/100;try{await audio.play();if(alive)status='Notification sound played.';}catch{error='Sound could not play. Check your browser sound settings.';}}
</script>
<h2 id="dialog-title">Notifications &amp; messages</h2><p class="small muted">Server preferences follow your account. Browser permission, sound and volume apply to this device.</p>
<form onsubmit={save}><label>Notify me in this community<select bind:value={serverMode}><option value="all">All new messages</option><option value="mentions">Mentions only</option><option value="none">Nothing</option></select></label>{#if channel}<label>For {channel.type==='dm'?'this direct message':'#'+channel.name}<select bind:value={channelMode} disabled={channel.type==='dm'}><option value="default">Use community preference</option><option value="all">All new messages</option><option value="mentions">Mentions only</option><option value="none">Nothing</option></select></label>{/if}<p class="small muted">Direct messages notify unless this community is set to Nothing. Messages you are reading at the bottom of the visible conversation stay quiet.</p><label class="check-label"><input type="checkbox" bind:checked={allowDms}/>Allow members of this community to send me direct messages</label><button class="primary" disabled={busy}>Save preferences</button></form>
<h3>On this device</h3><p class="small muted">Browser notifications appear while ChitChat is hidden and still running. They include the sender and message preview. A closed or suspended page cannot receive new messages; push notifications are not enabled.</p>{#if permission==='unsupported'}<p class="notice">This browser does not support desktop notifications here.</p>{:else if permission==='denied'}<p class="notice">Browser notifications are blocked. Change this site's notification permission in your browser settings to enable them.</p>{:else if device.desktop&&permission==='granted'}<button class="secondary" onclick={()=>onDevice({...device,desktop:false})}>Disable browser notifications</button>{:else}<button class="secondary" onclick={desktop}>Enable browser notifications</button>{/if}
<label class="check-label"><input type="checkbox" checked={device.sound} onchange={event=>onDevice({...device,sound:event.currentTarget.checked})}/>Play a notification sound</label><label>Notification volume: {device.volume}%<input type="range" min="0" max="100" step="1" value={device.volume} aria-label="Notification sound volume" oninput={event=>onDevice({...device,volume:Number(event.currentTarget.value)})}/></label><button class="secondary" onclick={testSound}>Test sound</button>
{#if error}<p class="error" role="alert">{error}</p>{/if}{#if status}<p class="notice" role="status">{status}</p>{/if}
